window.AUTH=window.AUTH||{};window.AUTH["18-1233"]={"d":"18-1233","id":"2019/18-1233","n":"Romag Fasteners, Inc. v. Fossil, Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioner Romag Fasteners, Inc.","date":"2019-09-13","url":"https://www.supremecourt.gov/DocketPDF/18/18-1233/115716/20190913120727028_Romag%20Opening%20Brief_9.13.19.pdf","side":"pet","n":82},{"k":"respondent","label":"Brief of respondents Fossil, Inc., et al.","date":"2019-11-27","url":"https://www.supremecourt.gov/DocketPDF/18/18-1233/123883/20191127125811705_18-1233bs.pdf","side":"res","n":138},{"k":"reply","label":"Reply of petitioner Romag Fasteners, Inc.","date":"2019-12-27","url":"https://www.supremecourt.gov/DocketPDF/18/18-1233/126876/20191227135424348_18-1233ReplyBriefForThePetitioner.pdf","side":"pet","n":59}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US1PP_web.pdf#page=228","tr":true,"items":[{"t":"case","label":"4 Pillar Dynasty LLC v. N.Y. & Co.","cite":"933 F.3d 202","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/933/202/","by":{"0":"14, 19"}},{"t":"case","label":"A & H Sportswear, Inc. v. Victoria’s Secret Stores, Inc.","cite":"237 F.3d 198","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/237/198/","by":{"0":"6, 36"}},{"t":"case","label":"Bambu Sales, Inc. v. Ozak Trading Inc.","cite":"58 F.3d 849","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/58/849/","by":{"0":"14"}},{"t":"case","label":"Banjo Buddies, Inc. v. Renosky","cite":"399 F.3d 168","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/399/168/","by":{"0":"42","1":"10"}},{"t":"case","label":"Bates v. United States","cite":"522 U.S. 23","y":1997,"id":"1997/96-7185","sc":1,"sum":"The Court held that the specific intent to injure or defraud someone, whether the United States or another, is not an element of the misapplication of funds proscribed by section 1097(a).","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Carter v. United States","cite":"530 U.S. 255","y":2000,"id":"1999/99-5716","sc":1,"sum":"The Court held that federal bank larceny is not a \"lesser included offense\" of federal bank robbery. The \"[p]etitioner is accordingly prohibited as a matter of law from obtaining a lesser included offense instruction,\" wrote Justice Thomas for the Court.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Catalina Lighting, Inc. v. Lamps Plus, Inc.","cite":"295 F.3d 1277","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/295/1277/","by":{"0":"48"}},{"t":"case","label":"Champion Spark Plug Co. v. Sanders","cite":"331 U.S. 125","y":1947,"id":"scdb/1946-093","sc":1,"ar":3,"sum":"The equities of this case are satisfied by a decree requiring that the word \"repaired\" or \"used\" be plainly and durably stamped on each plug and that the containers and printed matter used in connection with the sales clearly show that the plugs are used and reconditioned by respondents, giving their names and address-even though the decree does not require that the trade marks be removed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","1":"passim","2":"12"}},{"t":"case","label":"Church & Dwight Co. v. Russ","cite":"99 F. 276","y":1900,"court":"D. Ind.","url":"https://www.courtlistener.com/c/F./99/276/","by":{"0":"40","1":"40, 41","2":"15"}},{"t":"case","label":"Davis v. Mich. Dep’t of Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"sum":"Section 111 allows a state to tax income paid by the federal government \"if the taxation does not discriminate against the officer or employee because of the source of the pay or compensation.\" Because the Court found no \"significant differences between the two classes [federal and state employees],\" it held that the Michigan tax distinguished between employees solely on \"the source of the pay.\".","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"op":1,"sum":"The Court held that 18 U.S.C. Section 924(c)(1)(A)(iii) does not require proof of intent to discharge a firearm in order to enhance a sentence.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Dep’t of Homeland Sec. v. MacLean","cite":"135 S. Ct. 913","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/913/","sc":1,"by":{"0":"22"}},{"t":"case","label":"Dobson v. Dornan","cite":"118 U.S. 10","y":1886,"id":"scdb/1885-225","sc":1,"sum":"The specification oí letters patent for a design for a carpet, which is accompanied by a photographic illustration, and merely states that the nature of the design is fully represented in such illustration, and claims “the configuration of the design hereunto annexed, when applied to carpeting,” sets forth a sufficient description and claim, and the patent is valid.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"eBay Inc. v. MercExchange, L.L.C.","cite":"547 U.S. 388","y":2006,"id":"2005/05-130","sc":1,"op":1,"sum":"Held that the appeals court's general rule was an unwarranted departure from the traditional four-part test applied to determine whether an injunction is necessary.","sumSrc":"Oyez","by":{"0":"32","1":"14, 17, 47, 48"}},{"t":"case","label":"Elgin v. Nat’l Watch Co. v. Ill. Watch Case Co.","cite":"179 U.S. 665","y":1901,"id":"scdb/1900-085","sc":1,"sum":"The term trade mark means a distinctive mark of authenticity, through which the products of particular manufacturers or the vendible commodities of particular merchants may be distinguished from those of others.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"38, 40","2":"11"}},{"t":"case","label":"Fishman Transducers, Inc. v. Paul","cite":"684 F.3d 187","y":2012,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/684/187/","by":{"0":"45"}},{"t":"case","label":"Fogerty v. Fantasy, Inc.","cite":"510 U.S. 517","y":1994,"id":"1993/92-1750","sc":1,"ar":1,"sum":"The Court held that while attorney's fees are awarded from time to time to prevailing defendants or plaintiffs, this practice is entirely subject to the deciding court's discretion. Indeed, the Court observed, that the statute in question emphasizes such discretion by stating in relevant part that a court \"may\" award attorney's fees.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"George Basch Co. v. Blue Coral, Inc.","cite":"968 F.2d 1532","y":1992,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/968/1532/","by":{"0":"13, 14, 19","1":"passim"}},{"t":"case","label":"George T. Stagg Co. v. Taylor","cite":"27 S.W. 247","y":1894,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W./27/247/","by":{"0":"39","1":"31, 33, 34"}},{"t":"case","label":"Globe-Wernicke Co. v. Safe-Cabinet Co.","cite":"144 N.E. 711","y":1924,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E./144/711/","op":1,"by":{"0":"39","2":"16"}},{"t":"case","label":"Halo Elecs., Inc. v. Pulse Elecs., Inc.","cite":"136 S. Ct. 1923","y":2016,"id":"2015/14-1513","sc":1,"ar":4,"sum":"The Court determined that the rigid two-part test is not necessary for determining whether a patentee is eligible for enhanced damages under 35 U.S.C §284.","sumSrc":"Oyez","by":{"0":"30, 31","1":"14, 47"}},{"t":"case","label":"Hamilton-Brown Shoe Co. v. Wolf Bros. & Co.","cite":"240 U.S. 251","y":1916,"id":"scdb/1915-097","sc":1,"ar":1,"sum":"The words “The American Girl” as applied to women’s shoes is not a geographical or descriptive term signifying that the articles are manufactured in America, or intended to be.sold therein; nor does it indicate qualities or characteristics of the article.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"36, 37, 39","2":"13, 18, 22"}},{"t":"case","label":"Hartford Underwriters Ins. Co. v. Union Planters Bank, NA","cite":"530 U.S. 1","y":2000,"id":"1999/99-409","sc":1,"sum":"The Court held that \"Section 506(c) does not provide an administrative claimant of a bankruptcy estate an independent right to seek payment of its claim from property encumbered by a secured creditor's lien, or subject to secured claims.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Hecht Co. v. Bowles","cite":"321 U.S. 321","y":1944,"id":"scdb/1943-092","sc":1,"sum":"1. Under § 205 (a) of the Emergency Price Control Act of 1942, the grant of an injunction, upon application of the Administrator and a showing that the defendant has engaged in acts or practices violative of § 4 of the Act, is not mandatory but is in the discretion of the court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30","1":"45","2":"8"}},{"t":"case","label":"Horlick’s Malted Milk Co. v. Horluck’s, Inc.","cite":"51 F.2d 357","y":1931,"court":"W.D. Wash.","url":"https://www.courtlistener.com/c/F.2d/51/357/","op":1,"sum":"Explaining that the plaintiff “cannot recover defendant's profts unless it has been shown beyond a reasonable doubt that defendant was guilty of willful fraud in the use of the enjoined trade-name”.","sumSrc":"opinion","by":{"0":"42","1":"42","2":"17, 20"}},{"t":"case","label":"Howard Johnson Co. v. Khimani","cite":"892 F.2d 1512","y":1990,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/892/1512/","by":{"0":"42"}},{"t":"case","label":"Int’l Star Class Yacht Racing Ass’n v. Tommy Hilfiger, U.S.A., Inc.","cite":"80 F.3d 749","y":1996,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/80/749/","by":{"0":"13, 45"}},{"t":"case","label":"Isbrandtsen Co. v. Johnson","cite":"343 U.S. 779","y":1952,"id":"scdb/1951-093","sc":1,"sum":"In an admiralty proceeding by a seaman against his employer to recover wages earned on a merchant vessel of United States registry, the employer may not set off against the seaman's wages its expenditures for the medical care and hospitalization of another member of the crew necessitated by injuries unjustifiably inflicted on him by the seaman during the voyage on which the wages were earned.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"I.T.S. Co. v. Tee Pee Rubber Co.","cite":"288 F. 794","y":1923,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F./288/794/","by":{"0":"37","1":"38, 43","2":"15, 16"}},{"t":"case","label":"Keene Corp. v. United States","cite":"508 U.S. 200","y":1993,"id":"1992/92-166","sc":1,"sum":"Petitioner Keene Corporation has been sued by thousands of plaintiffs alleging injury from exposure to asbestos fibers and dust released from Keene products. Claiming that it was following Government specifications in including asbestos within products supplied to Government projects, and that it actually bought asbestos fiber from the Government, Keene filed two complaints against the United States in the Court of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"King v. St. Vincent’s Hosp.","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"sum":"Section 2024(d) does not limit the length of military service after which a member of the Armed Forces retains a right to civilian reemployment. Subsection (d)'s text-which specifies that any covered employee \"shall... be granted a leave... for the period required to perform active duty [and] [u]pon... release from... such duty... shall be permitted to return to [his or her] position\"-is utterly silent about any …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"136 S. Ct. 1979","y":2016,"id":"2015/15-375","sc":1,"sum":"The Court determined that, when deciding whether to grant attorney’s fees under Section 505 of the Copyright Act, courts should give substantial weight to the objective reasonableness of the losing party’s position, but that determination should not be the controlling factor.","sumSrc":"Oyez","by":{"0":"31, 32","1":"48"}},{"t":"case","label":"Lamie v. U.S. Tr.","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Laukus v. Rio Brands","cite":"391 F. App’x 416","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/391/416/","by":{"0":"42"}},{"t":"case","label":"Lawrence-Williams Co. v. Societe Enfants Gombault et Cie","cite":"52 F.2d 774","y":1931,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/52/774/","op":2,"by":{"0":"39","1":"39","2":"14, 15"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"23","1":"25"}},{"t":"case","label":"McLean v. Fleming","cite":"96 U.S. 245","y":1877,"id":"scdb/1877-223","sc":1,"ar":4,"sum":"The bill in this case was filed. June 1, 1872, by Cochrane Fleming, to restrain the alleged infringement of his trade-mark for liver pills, by Jlimes H. McLean.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"39, 40","1":"33, 40, 41","2":"14"}},{"t":"case","label":"Minn. Pet Breeders, Inc. v. Schell & Kampeter, Inc.","cite":"41 F.3d 1242","y":1994,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/41/1242/","by":{"0":"19","1":"20, 46"}},{"t":"case","label":"Mishawaka Rubber Mfg. Co. v. S.S. Kresge Co.","cite":"316 U.S. 203","y":1942,"id":"scdb/1941-095","sc":1,"sum":"In order that he may recover profits under § 19 of the Trademark Act, the trademark owner is not required to prove that the purchasers of goods bearing the infringing mark were induced by it to believe that the goods were the goods of the trademark owner and purchased for that reason, and that they would otherwise have bought of him. P. 206. 119 F. 2d 316, reversed. CERTIORARI, 314 U. S. 603, to review the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","1":"7, 39","2":"12, 13, 14"}},{"t":"case","label":"Mississippi ex rel. Hood v. AU Optronics Corp.","cite":"571 U.S. 161","y":2014,"id":"2013/12-1036","sc":1,"sum":"The Court ruled that, in order for a case to be removed to a federal district court instead of a state court under the Class Action Fairness Act, at least 100 people must be represented by the lawsuit.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"op":1,"ar":2,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35","1":"18"}},{"t":"case","label":"Moseley v. V Secret Catalogue, Inc.","cite":"537 U.S. 418","y":2003,"id":"2002/01-1015","sc":1,"sum":"Justice John Paul Stevens delivered the opinion for a unanimous Court with respect to parts I, II, and IV of the opinion, which held that the FTDA requires proof of actual dilution.","sumSrc":"Oyez","by":{"0":"7","1":"15, 22"}},{"t":"case","label":"N.K. Fairbank Co. v. Windsor","cite":"124 F. 200","y":1903,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F./124/200/","by":{"0":"34"}},{"t":"case","label":"Oakes v. Tonsmierre","cite":"49 F. 447","y":1883,"court":"S.D. Ala.","url":"https://www.courtlistener.com/c/F./49/447/","op":1,"ar":7,"sum":"Noting only that an account “may” occur.","sumSrc":"brief:1","by":{"0":"37","1":"34, 43","2":"14"}},{"t":"case","label":"Octane Fitness, LLC v. ICON Health & Fitness, Inc.","cite":"572 U.S. 545","y":2014,"id":"2013/12-1184","sc":1,"sum":"A case in which the Court defined \"exceptional\" cases as ones that simply stand out from others due to a frivolous nature related to its legal claims.","sumSrc":"Oyez","by":{"0":"31, 32","1":"49"}},{"t":"case","label":"Pac. Operators Offshore, LLP v. Valladolid","cite":"565 U.S. 207","y":2012,"id":"2011/10-507","sc":1,"sum":"The Court held that the Outer Continental Shelf Lands Act extends coverage for injuries that occurred as the result of operations conducted on the outer continental shelf to an employee, as long as the employee can establish a substantial connection between the injury and the employer’s extractive operations.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Park ’N Fly, Inc. v. Dollar Park & Fly, Inc.","cite":"469 U.S. 189","y":1985,"id":"1984/83-1132","sc":1,"sum":"The holder of a registered mark may rely on incontestability to enjoin infringement, and an infringement action may not be defended on the grounds that the mark is merely descriptive.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 33, 34","1":"44, 50, 54","2":"9"}},{"t":"case","label":"P.E. Sharpless Co. v. Lawrence","cite":"213 F. 423","y":1914,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F./213/423/","by":{"0":"37, 38, 43","1":"41, 43","2":"11, 15, 16"}},{"t":"case","label":"Pebble Beach Co. v. Tour 18 I Ltd.","cite":"155 F.3d 526","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/155/526/","by":{"0":"42","1":"21"}},{"t":"case","label":"Prest-O-Lite Co. v. Bournonville","cite":"260 F. 442","y":1915,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F./260/442/","ar":3,"sum":"Stating that “the same rules cannot always be applied” and that “proof of actual fraud or intent to divert * * * business” had been required for a profits award in trademark cases.","sumSrc":"brief:1","by":{"0":"43","1":"41, 42, 43","2":"11, 16"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Tr.","cite":"136 S. Ct. 1938","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Quick Techs., Inc. v. Sage Grp. PLC","cite":"313 F.3d 338","y":2002,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/313/338/","by":{"0":"19"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Ramdass v. Angelone","cite":"530 U.S. 156","y":2000,"id":"1999/99-7000","sc":1,"sum":"The Court held that Ramdass was not entitled to federal habeas corpus relief because he was not entitled to instruction on parole ineligibility at sentencing since conviction had not been entered yet on the earlier jury verdict making him parole ineligible.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Regis v. Jaynes","cite":"77 N.E. 774","y":1906,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./77/774/","op":1,"ar":1,"by":{"0":"43","1":"34, 35, 36","2":"18"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil, Inc.","cite":"979 F. Supp. 2d 264","y":2013,"court":"D. Conn.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/979/264/","by":{"0":"13"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil, Inc.","cite":"29 F. Supp. 3d 85","y":2014,"court":"D. Conn.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/29/85/","by":{"0":"1"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil, Inc.","cite":"686 F. App’x 889","y":2017,"url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/686/889/","by":{"0":"1"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil, Inc.","cite":"137 S. Ct. 1373","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./137/1373/","sc":1,"by":{"0":"15","1":"10"}},{"t":"case","label":"Roulo v. Russ Berrie & Co.","cite":"886 F.2d 931","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/886/931/","by":{"0":"42","1":"21"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Saxlehner v. Siegel-Cooper Co.","cite":"179 U.S. 42","y":1900,"id":"scdb/1900-003","sc":1,"op":1,"sum":"Holding that one defendant “should not be required to account for gains and profts” when it “appear[ed] to have acted in good faith”.","sumSrc":"opinion","by":{"0":"37","1":"33, 40, 42"}},{"t":"case","label":"SCA Hygiene Prods. Aktiebolag v. First Quality Baby Prods., LLC","cite":"137 S. Ct. 954","y":2017,"id":"2016/15-927","sc":1,"sum":"The Court determined that an unreasonable delay in litigation cannot bar claims for patent infringement that are brought within the six-year statutory period of limitations.","sumSrc":"Oyez","by":{"0":"1, 15","1":"10"}},{"t":"case","label":"Sheldon v. Metro-Goldwyn Pictures Corp.","cite":"309 U.S. 390","y":1940,"id":"scdb/1939-111","sc":1,"op":1,"sum":"1. That clause of § 25 (b) of the Copyright Act which authorizes recovery from an infringer, \"in lieu of actual damages and profits,\" of \"such 'damages as to the court shall appear to be just,\" is inapplicable where the only matter in question is the apportionment of profits established.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Stonebraker v. Stonebraker","cite":"33 Md. 252","y":1870,"url":"https://www.courtlistener.com/c/Md./33/252/","op":2,"by":{"0":"38","1":"38, 40","2":"14"}},{"t":"case","label":"Straus v. Notaseme Hosiery Co.","cite":"240 U.S. 179","y":1916,"id":"scdb/1915-089","sc":1,"sum":"While one using an unregistered design similar to that-adopted earlier by another may be enjoined from further use thereof, he may not be charged with profits' if it appear that the original imitation -was unintentional, that no deceit or substitution of goods was accomplished in fact,' and that no considerable part of the business was due to his goods being supposed to be those of. the earlier user of the design..","sumSrc":"Headnote (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Swann v. Charlotte-Mecklenberg Bd. of Educ.","cite":"402 U.S. 1","y":1971,"id":"1970/281","sc":1,"sum":"The Court held that once violations of previous mandates directed at desegregating schools occurred, the scope of district courts' powers to correct problems were broad and flexible in nature.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Synergistic Int’l, LLC v. Korman","cite":"470 F.3d 162","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/470/162/","by":{"0":"42"}},{"t":"case","label":"Tilghman v. Proctor","cite":"125 U.S. 136","y":1888,"id":"scdb/1887-171","sc":1,"sum":"One having an interest in all fees and other sums to be recovered under a patent, but not shown to have'any interest, legal or equitable, in the patent itself, need not be made a party to a bill in equity for its infringement.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Two Pesos, Inc. v. Taco Cabana, Inc.","cite":"505 U.S. 763","y":1992,"id":"1991/91-971","sc":1,"sum":"The Supreme Court held that trade dress can be protected under the Lanham Act based on inherent distinctiveness even if there is no proof of a secondary meaning. Recovery is usually available for trademark infringement without a secondary meaning, and there is no persuasive reason for treating trade dress differently from other types of trademark.","sumSrc":"Oyez","by":{"0":"6, 7, 35, 41","2":"11"}},{"t":"case","label":"United States v. Craft","cite":"535 U.S. 274","y":2002,"id":"2001/00-1831","sc":1,"sum":"The Court held that each tenant possesses individual rights in the estate sufficient to constitute \"property\" or \"rights to property\" for the purposes of the lien.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"United States v. Paradise","cite":"480 U.S. 149","y":1987,"id":"1986/85-999","sc":1,"sum":"It is important to remember that courts had first found the Department's practices unconstitutional in 1972.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"law","label":"Pub. L. No. 100-667","url":"https://www.govinfo.gov/link/statute/102/3935","by":{"0":"42","2":"12"}},{"t":"law","label":"Pub. L. No. 104-98","url":"https://www.govinfo.gov/link/plaw/104/public/98","by":{"0":"14","1":"24"}},{"t":"law","label":"Pub. L. No. 106-43","url":"https://www.govinfo.gov/link/plaw/106/public/43","by":{"0":"14","1":"10, 24","2":"5"}},{"t":"law","label":"Pub. L. No. 106-113","url":"https://www.govinfo.gov/link/plaw/106/public/113","by":{"0":"14","1":"24"}},{"t":"law","label":"Pub. L. No. 107-273","url":"https://www.govinfo.gov/link/plaw/107/public/273","by":{"0":"14"}},{"t":"usc","label":"15 U.S.C. § 1111","url":"https://www.law.cornell.edu/uscode/text/15/1111","stext":{"head":"§1111. Notice of registration; display with mark; recovery of profits and damages in infringement suit","paras":[[0,"Notwithstanding the provisions of section 1072 of this title, a registrant of a mark registered in the Patent and Trademark Office, may give notice that his mark is registered by displaying with the mark the words \"Registered in U.S. Patent and Trademark Office\" or \"Reg. U.S. Pat. & Tm. Off.\" or the letter R enclosed within a circle, thus ®; and in any suit for infringement under this chapter by such a registrant failing to give such notice of registration, no profits and no damages shall be recovered under the provisions of this chapter unless the defendant had actual notice of the registration."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1111?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1111. Notice of registration; display with mark; recovery of profits and damages in infringement suit","tname":"Commerce and Trade","by":{"0":"2, 9, 20","1":"16, 22, 25","2":"2"}},{"t":"usc","label":"17 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/17/504","subs":["(a)(1)","(b)"],"stext":{"head":"§504. Remedies for infringement: Damages and profits","paras":[[0,"(a) In General.—Except as otherwise provided by this title, an infringer of copyright is liable for either—"],[1,"(1) the copyright owner's actual damages and any additional profits of the infringer, as provided by subsection (b); or"],[1,"(2) statutory damages, as provided by subsection (c)."],[0,"(b) Actual Damages and Profits.—The copyright owner is entitled to recover the actual damages suffered by him or her as a result of the infringement, and any profits of the infringer that are attributable to the infringement and are not taken into account in computing the actual damages. In establishing the infringer's profits, the copyright owner is required to present proof only of the infringer's gross revenue, and the infringer is required to prove his or her deductible expenses and the elements of profit attributable to factors other than the copyrighted work."],[0,"(c) Statutory Damages.—"],[1,"(1) Except as provided by clause (2) of this subsection, the copyright owner may elect, at any time before final judgment is rendered, to recover, instead of actual damages and profits, an award of statutory damages for all infringements involved in the action, with respect to any one work, for which any one infringer is liable individually, or for which any two or more infringers are liable jointly and severally, in a sum of not less than $750 or more than $30,000 as the court considers just. For the purposes of this subsection, all the parts of a compilation or derivative work constitute one work."],[1,"(2) In a case where the copyright owner sustains the burden of proving, and the court finds, that infringement was committed willfully, the court in its discretion may increase the award of statutory damages to a sum of not more than $150,000. In a case where the infringer sustains the burden of proving, and the court finds, that such infringer was not aware and had no reason to believe that his or her acts constituted an infringement of copyright, the court in its discretion may reduce the award of statutory damages to a sum of not less than $200. The court shall remit statutory damages in any case where an infringer believed and had reasonable grounds for believing that his or her use of the copyrighted work was a fair use under section 107, if the infringer was: (i) an employee or agent of a nonprofit educational institution, library, or archives acting within the scope of his or her employment who, or such institution, library, or archives itself, which infringed by reproducing the work in copies or phonorecords; or (ii) a public broadcasting entity which or a person who, as a regular part of the nonprofit activities of a public broadcasting entity (as defined in section 118(f)) infringed by performing a published nondramatic literary work or by reproducing a transmission program embodying a performance of such a work."],[1,"(3)(A) In a case of infringement, it shall be a rebuttable presumption that the infringement was committed willfully for purposes of determining relief if the violator, or a person acting in concert with the violator, knowingly provided or knowingly caused to be provided materially false contact information to a domain name registrar, domain name registry, or other domain name registration authority in registering, maintaining, or renewing a domain name used in connection with the infringement."],[1,"(B) Nothing in this paragraph limits what may be considered willful infringement under this subsection."],[1,"(C) For purposes of this paragraph, the term \"domain name\" has the meaning given that term in section 45 of the Act entitled \"An Act to provide for the registration and protection of trademarks used in commerce, to carry out the provisions of certain international conventions, and for other purposes\" approved July 5, 1946 (commonly referred to as the \"Trademark Act of 1946\"; 15 U.S.C. 1127)."],[0,"(d) Additional Damages in Certain Cases.—In any case in which the court finds that a defendant proprietor of an establishment who claims as a defense that its activities were exempt under section 110(5) did not have reasonable grounds to believe that its use of a copyrighted work was exempt under such section, the plaintiff shall be entitled to, in addition to any award of damages under this section, an additional award of two times the amount of the license fee that the proprietor of the establishment concerned should have paid the plaintiff for such use during the preceding period of up to 3 years."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/504?type=usc&year=mostrecent&link-type=html"},"head":"§504. Remedies for infringement: Damages and profits","tname":"Copyrights","by":{"0":"48","1":"55, 55"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"usc","label":"35 U.S.C. § 283","url":"https://www.law.cornell.edu/uscode/text/35/283","stext":{"head":"§283. Injunction","paras":[[0,"The several courts having jurisdiction of cases under this title may grant injunctions in accordance with the principles of equity to prevent the violation of any right secured by patent, on such terms as the court deems reasonable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/283?type=usc&year=mostrecent&link-type=html"},"head":"§283. Injunction","tname":"Patents","by":{"0":"32","1":"17, 47"}},{"t":"case","label":"Aladdin Mfg. Co. v. Mantle Lamp Co. of Am.","cite":"116 F.2d 708","y":1941,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/116/708/","by":{"1":"36"}},{"t":"case","label":"ALPO Petfoods, Inc. v. Ralston Purina Co.","cite":"913 F.2d 958","y":1990,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/913/958/","by":{"1":"19, 52, 53"}},{"t":"case","label":"Arlington Cent. Sch. Dist. Bd. of Educ. v. Murphy","cite":"548 U.S. 291","y":2006,"id":"2005/05-18","sc":1,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that IDEA did not authorize reimbursement of expert fees. \"While authorizing the award of reasonable attorney's fees, the Act contains detailed provisions that are designed to ensure that such awards are indeed reasonable,\" Justice Alito wrote. \"The absence of any comparable provisions relating to expert fees strongly suggests that recovery of expert fees is not authorized.\" Justice Alito went on to write that the case was made even simpler by the fact that, as an exercise of Congress's Spending Clause power, any provision requiring reimbursement of expert fees would have had to be \"unambiguous,\" which it clearly was not.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Aro Mfg. Co. v. Convertible Top Replacement Co.","cite":"377 U.S. 476","y":1964,"id":"1963/75","sc":1,"sum":"Respondent was the assignee of certain territorial rights in a combination patent for a top-structure for convertible automobiles. The patent covered only the combination of several unpatented components and made no claim to invention based on the fabric used in the top-structure. Top-structures using the patented combination were included in 1952-1954 cars made by General Motors Corp., pursuant to a patent license, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"55"}},{"t":"case","label":"Avery v. Meikle","cite":"3 S.W. 609","y":1887,"court":"Ky. Ct. App.","url":"https://www.courtlistener.com/c/S.W./3/609/","by":{"1":"53"}},{"t":"case","label":"Bandag, Inc. v. Al Bolser’s Tire Stores, Inc.","cite":"750 F.2d 903","y":1984,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/750/903/","by":{"1":"20"}},{"t":"case","label":"Basketball Mktg. Co. v. Upscale Entm't & Mktg. Grp.","cite":"227 F. App’x 492","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/227/492/","by":{"1":"51"}},{"t":"case","label":"Beebe v. Tolerton & Stetson Co.","cite":"91 N.W. 905","y":1902,"url":"https://www.courtlistener.com/c/N.W./91/905/","sum":"Stating, even before 1916, that to receive profits, a “plaintiff must show that defendant acted in bad faith,” citing Saxlehner.","sumSrc":"brief:1","by":{"1":"42"}},{"t":"case","label":"Bishop v. Equinox Int’l Corp.","cite":"154 F.3d 1220","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/154/1220/","ar":1,"by":{"1":"20"}},{"t":"case","label":"Burger King Corp. v. Mason","cite":"855 F.2d 779","y":1988,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/855/779/","by":{"1":"20"}},{"t":"case","label":"Cannon v. Univ. of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Commil USA, LLC v. Cisco Sys., Inc.","cite":"135 S. Ct. 1920","y":2015,"id":"2014/13-896","sc":1,"sum":"The Court decided that a good-faith belief that a patent is invalid is not a defense to a claim of induced infringement.","sumSrc":"Oyez","by":{"1":"50"}},{"t":"case","label":"Dickey v. Mutual Film Corp.","cite":"160 N.Y.S. 609","y":1916,"court":"Sup. Ct.","url":"https://www.courtlistener.com/c/N.Y.S./160/609/","by":{"1":"37"}},{"t":"case","label":"Dickey v. Mutual Film Corp.","cite":"186 A.D. 701","y":1919,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/A.D./186/701/","by":{"1":"37","2":"18, 19"}},{"t":"case","label":"Dir. of Revenue of Mo. v. CoBank ACB","cite":"531 U.S. 316","y":2001,"id":"2000/99-1792","sc":1,"sum":"The Court held that banks for cooperatives are subject to taxation. Justice Thomas wrote for the Court that nothing in the 1985 amendments to the Farm Credit Act indicated a repeal of the previous express approval of state taxation and that the structure of the Act indicated by negative implication that banks for cooperatives were not entitled to immunity.","sumSrc":"Oyez","by":{"1":"10, 21"}},{"t":"case","label":"Donner v. Parker Credit Corp.","cite":"76 A.2d 277","y":1950,"court":"N.J. Super. Ct. Ch. Div.","url":"https://www.courtlistener.com/c/A.2d/76/277/","by":{"1":"42","2":"17"}},{"t":"case","label":"Dr. A. Reed Cushion Shoe Co. v. Frew","cite":"158 F. 552","y":1908,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F./158/552/","by":{"1":"36","2":"17, 19"}},{"t":"case","label":"Foxtrap, Inc. v. Foxtrap, Inc.","cite":"671 F.2d 636","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/671/636/","by":{"1":"20"}},{"t":"case","label":"Franklin Simon & Co. v. Bramley Blouses, Inc.","cite":"10 N.Y.S.2d 42","y":1939,"court":"Sup. Ct.","url":"https://www.courtlistener.com/c/N.Y.S.2d/10/42/","by":{"1":"35"}},{"t":"case","label":"Frazer v. Frazer Lubricator Co.","cite":"18 Ill. App. 450","y":1886,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/Ill.%20App./18/450/","by":{"1":"31"}},{"t":"case","label":"Fred Fisher Music Co. v. M. Witmark & Sons","cite":"318 U.S. 643","y":1943,"id":"scdb/1942-119","sc":1,"sum":"Under the Copyright Act of 1909, as amended, an author's right to obtain a renewal and extension of his copyright is assignable by him by an agreement made before the expiration of the original copyright term. P. 656. 125 F. 2d 949, affirmed. CERTIORARI, 317 U. S. 611, to review the affirmance of a decree of the District Court, 38 F. Supp. 72, granting an interlocutory injunction in a case of alleged copyright …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39","2":"17"}},{"t":"case","label":"George W. Luft Co. v. Zande Cosmetic Co.","cite":"48 F. Supp. 602","y":1942,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./48/602/","by":{"1":"36"}},{"t":"case","label":"Golden W. Brewing Co. v. Milonas & Sons, Inc.","cite":"104 F.2d 880","y":1939,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/104/880/","sum":"Recognizing that the 1905 Act preserved equitable defenses of “laches, acquiescence and the absence of wrongful intent”.","sumSrc":"brief:1","by":{"1":"35"}},{"t":"case","label":"Gorham Mfg. Co. v. Schmidt","cite":"196 F. 955","y":1912,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./196/955/","ar":1,"by":{"1":"36, 40, 41","2":"20"}},{"t":"case","label":"Graham v. Plate","cite":"40 Cal. 593","y":1871,"url":"https://www.courtlistener.com/c/Cal./40/593/","op":1,"by":{"1":"33"}},{"t":"case","label":"Great-West Life & Annuity Ins. Co. v. Knudson","cite":"534 U.S. 204","y":2002,"id":"2001/99-1786","sc":1,"sum":"The Court held that because Great-West is seeking legal relief - the imposition of personal liability on Knudson for a contractual obligation to pay money - ERISA does not authorize this action.","sumSrc":"Oyez","by":{"1":"17, 26, 30"}},{"t":"case","label":"Gross v. FBL Fin. Servs., Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"1":"25","2":"5"}},{"t":"case","label":"Gulden v. Chance","cite":"182 F. 303","y":1910,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F./182/303/","by":{"1":"43"}},{"t":"case","label":"Hanover Star Milling Co. v. Metcalf","cite":"240 U.S. 403","y":1916,"id":"scdb/1915-112","sc":1,"sum":"Two District Courts in different circuits having'granted temporary -injunctions, and both Circuit Courts of Appeals having reversed upon grounds that went to the merits and differed upon fundamental questionsaffecting the same trade-mark,' writs of.certiorari.were allowed by this court before final decrees, notwithstanding the general rule to the contrary.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"42","2":"13"}},{"t":"case","label":"Helsinn Healthcare S.A. v. Teva Pharm. USA, Inc.","cite":"139 S. Ct. 628","y":2019,"id":"2018/17-1229","sc":1,"sum":"The sale of an invention to a third party who is obligated to keep the invention confidential may place the invention “on sale” for purposes of the Leahy-Smith America Invents Act, which bars a person from receiving a patent on an invention that was “in public use, on sale, or otherwise available to the public before the effective filing date of the claimed invention,” 35 U. S. C. §102(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"12, 18"}},{"t":"case","label":"Hemmeter Cigar Co. v. Congress Cigar Co.","cite":"118 F.2d 64","y":1941,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/118/64/","op":1,"by":{"1":"39","2":"15"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"1":"54"}},{"t":"case","label":"Hostetter v. Vowinkle","cite":"12 F. Cas. 546","y":1871,"court":"C.C.D. Neb.","url":"https://www.courtlistener.com/c/F.%20Cas./12/546/","op":1,"by":{"1":"33"}},{"t":"case","label":"Indep. Fed’n of Flight Attendants v. Zipes","cite":"491 U.S. 754","y":1989,"id":"1988/88-608","sc":1,"sum":"District courts may award Title VII attorney's fees against those who are not charged with Title VII violations but intervene to protect their own rights only where the intervention is frivolous, unreasonable, or without foundation. Assessing fees against blameless intervenors is not essential to § 706(k)'s central purpose of providing victims of wrongful discrimination an incentive to file suit. The prospect of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Inwood Labs., Inc. v. Ives Labs., Inc.","cite":"456 U.S. 844","y":1982,"id":"1981/80-2182","sc":1,"sum":"The Court of Appeals erred in setting aside the District Court's findings of fact.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26","2":"11"}},{"t":"case","label":"Jones v. Roshenberger","cite":"144 N.E. 858","y":1924,"court":"Ind. App.","url":"https://www.courtlistener.com/c/N.E./144/858/","by":{"1":"42"}},{"t":"case","label":"Kickapoo Dev. Corp. v. Kickapoo Orchard Co.","cite":"285 N.W. 354","y":1939,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W./285/354/","by":{"1":"42"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"sum":"The Court found that there is not geographical restriction on the \"first sale\" copyright doctrine.","sumSrc":"Oyez","by":{"1":"12, 17"}},{"t":"case","label":"La Republique Francaise v. Schultz","cite":"102 F. 153","y":1900,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F./102/153/","by":{"1":"34"}},{"t":"case","label":"Liberty Oil Corp. v. Crowley, Milner & Co.","cite":"258 N.W. 241","y":1935,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./258/241/","ar":1,"by":{"1":"36","2":"18, 19"}},{"t":"case","label":"Lonchar v. Thomas","cite":"517 U.S. 314","y":1996,"id":"1995/95-5015","sc":1,"sum":"The Court held that federal Habeas Corpus Rule 9, not some general \"equitable\" power to create exceptions to the Rule, should have determined whether or not a petition's dismissal was appropriate.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Louis Vuitton Malletier S.A. v. LY USA, Inc.","cite":"676 F.3d 83","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/676/83/","by":{"1":"27"}},{"t":"case","label":"Ludington Novelty Co. v. Leonard","cite":"127 F. 155","y":1903,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F./127/155/","by":{"1":"29"}},{"t":"case","label":"Maier Brewing Co. v. Fleischmann Distilling Corp.","cite":"390 F.2d 117","y":1968,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/390/117/","by":{"1":"21"}},{"t":"case","label":"Martin v. Franklin Capital Corp.","cite":"546 U.S. 132","y":2005,"id":"2005/04-1140","sc":1,"sum":"The Court ruled that \"absent unusual circumstances, attorney's fees should not be awarded when the removing party has an objectively reasonable basis for removal.\" The Court admitted that Section 1447 is unclear on when attorney's fees should be added. The Court's reading of the statute detected no strong textual bias for or against awarding fees.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Matal v. Tam","cite":"137 S. Ct. 1744","y":2017,"id":"2016/15-1293","sc":1,"sum":"The Court determined that the Disparagement Clause prohibits trademarks that disparage the members of a racial or ethnic group and violates the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"50"}},{"t":"case","label":"Microsoft Corp. v. i4i Ltd. P’ship","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"sum":"The Court held that a challenge to a patent's validity must offer clear and convincing evidence.","sumSrc":"Oyez","by":{"1":"17, 19, 30"}},{"t":"case","label":"Mishawaka Rubber & Woolen Mfg. Co. v. S.S. Kresge Co.","cite":"119 F.2d 316","y":1941,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/119/316/","by":{"1":"40","2":"15"}},{"t":"case","label":"Monsanto Chem. Co. v. Perfect Fit Prods. Mfg. Co.","cite":"349 F.2d 389","y":1965,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/349/389/","by":{"1":"52"}},{"t":"case","label":"Montanile v. Bd. of Trs. of Nat’l Elevator Indus. Health Benefit Plan","cite":"136 S. Ct. 651","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/651/","sc":1,"by":{"1":"44","2":"9, 17"}},{"t":"case","label":"Morgenstern Chem. Co. v. G. D. Searle & Co.","cite":"253 F.2d 390","y":1958,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/253/390/","by":{"1":"46"}},{"t":"case","label":"Nalpac, Ltd. v. Corning Glass Works","cite":"784 F.2d 752","y":1986,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/784/752/","by":{"1":"20"}},{"t":"case","label":"O’Cedar Corp. v. F.W. Woolworth Co.","cite":"73 F.2d 366","y":1934,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/73/366/","by":{"1":"29"}},{"t":"case","label":"Oneida Cmty. v. Oneida Game Trap Co.","cite":"150 N.Y.S. 918","y":1914,"court":"Sup. Ct.","url":"https://www.courtlistener.com/c/N.Y.S./150/918/","by":{"1":"35","2":"19"}},{"t":"case","label":"Pease v. Scott Cty. Milling Co.","cite":"5 F.2d 524","y":1925,"court":"E.D. Mo.","url":"https://www.courtlistener.com/c/F.2d/5/524/","by":{"1":"36"}},{"t":"case","label":"Radio Shack Corp. v. Radio Shack, Inc.","cite":"180 F.2d 200","y":1950,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/180/200/","by":{"1":"21"}},{"t":"case","label":"Reading Stove Works, Orr, Painter & Co. v. S.M. Howes Co.","cite":"87 N.E. 751","y":1909,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./87/751/","ar":1,"by":{"1":"37","2":"18, 19"}},{"t":"case","label":"Rolex Watch USA, Inc. v. Meece","cite":"158 F.3d 816","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/158/816/","by":{"1":"21"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil, Inc.","cite":"139 S. Ct. 2778","y":2019,"url":"https://www.courtlistener.com/c/S.%20Ct./139/2778/","sc":1,"by":{"1":"11"}},{"t":"case","label":"SecuraComm Consulting Inc. v. Securacom Inc.","cite":"166 F.3d 182","y":1999,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/166/182/","by":{"1":"20, 29"}},{"t":"case","label":"Sony Corp. of Am. v. Universal City Studios, Inc.","cite":"464 U.S. 417","y":1984,"id":"1982/81-1687","sc":1,"sum":"The Court held that \"[t]he sale of the VTR's to the general public does not constitute contributory infringement of [Universal's] copyrights.\" The Court concluded that there was a significant likelihood that a substantial number of copyright holders who license their works for free public broadcasts would not object to having their broadcasts time-shifted by private viewers and that Universal failed to show that time-shifting would cause non-minimal harm to the potential market for, or the value of, their copyrighted works.","sumSrc":"Oyez","by":{"1":"55"}},{"t":"case","label":"Std. Cigar Co. v. Goldsmith","cite":"58 Pa. Super. 33","y":1914,"url":"https://www.courtlistener.com/c/Pa.%20Super./58/33/","op":1,"sum":"Reasoning that a defendant “should be compelled to account for . . . profts” where “the infringement complained of was not the result of mistake or ignorance of the plaintiff's right”.","sumSrc":"opinion","by":{"1":"36, 37","2":"20"}},{"t":"case","label":"Taylor v. Carpenter","cite":"11 Paige Ch. 292","y":1844,"court":"N.Y. Ch.","url":"https://www.courtlistener.com/c/Paige%20Ch./11/292/","sum":"Explaining that where a defendant uses a trademark “for the fraudulent purpose of inducing the public * * * to believe that it was in fact” the genuine article, the defendant is also liable for damages.","sumSrc":"brief:1","by":{"1":"33"}},{"t":"case","label":"Timbs v. Indiana","cite":"139 S. Ct. 682","y":2019,"id":"2018/17-1091","sc":1,"sum":"The Eighth Amendment’s Excessive Fines Clause is an incorporated protection applicable to the States under the Fourteenth Amendment’s Due Process Clause.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"43"}},{"t":"case","label":"United Dominion Indus., Inc. v. United States","cite":"532 U.S. 822","y":2001,"id":"2000/00-157","sc":1,"sum":"The Court held that an affiliated group's product liability loss must be figured on a consolidated, single-entity basis, and not by aggregating product liability losses separately determined company by company.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"United Drug Co. v. Kovacs","cite":"123 A. 654","y":1924,"court":"Pa.","url":"https://www.courtlistener.com/c/A./123/654/","by":{"1":"42"}},{"t":"case","label":"United Drug Co. v. Obear-Nester Glass Co.","cite":"111 F.2d 997","y":1940,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/111/997/","sum":"Noting that “[g]ood faith may have an effect upon the measure of damages recoverable under the statute” and affirming “an accounting and award of profits” given that the defendant acted “in bad faith”.","sumSrc":"brief:1","by":{"1":"36"}},{"t":"case","label":"Universal Health Servs., Inc. v. U.S. ex rel. Escobar","cite":"136 S. Ct. 1989","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1989/","sc":1,"by":{"1":"19"}},{"t":"case","label":"Valmor Prods. Co. v. Standard Prods. Corp.","cite":"464 F.2d 200","y":1972,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/464/200/","by":{"1":"21"}},{"t":"case","label":"Weinberger v. Romero-Barcelo","cite":"456 U.S. 305","y":1982,"id":"1981/80-1990","sc":1,"sum":"Held that the district court was not obligated to enjoin the Navy from operating on and around Vieques island. He emphasized the traditional flexibility of equitable remedies and courts’ responsibility to balance plaintiffs’ need for an injunction with the public utility of the enjoined action.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"William Rogers Mfg. Co. v. S. Mfg. Co.","cite":"11 F. 495","y":1882,"court":"C.C.D. Mass.","url":"https://www.courtlistener.com/c/F./11/495/","by":{"1":"33","2":"19"}},{"t":"case","label":"Winter v. Nat. Res. Def. Council, Inc.","cite":"555 U.S. 7","y":2008,"id":"2008/07-1239","sc":1,"sum":"The Court held that the standard for properly granting a preliminary injunction is not based on the \"possibility\" of irreparable harm to marine life, but rather that \"irreparable injury is likely\" in the absence of such an injunction.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Wood v. Peffer","cite":"130 P.2d 220","y":1942,"court":"Cal. Dist. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/130/220/","op":1,"sum":"Stating that “the same rules cannot always be applied” and that “proof of actual fraud or intent to divert * * * business” had been required for a profits award in trademark cases.","sumSrc":"brief:1","by":{"1":"41, 42","2":"18"}},{"t":"case","label":"W.R. Lynn Shoe Co. v. Auburn-Lynn Shoe Co.","cite":"62 A. 499","y":1905,"court":"Me.","url":"https://www.courtlistener.com/c/A./62/499/","by":{"1":"32"}},{"t":"usc","label":"36 U.S.C. § 220506","url":"https://www.law.cornell.edu/uscode/text/36/220506","by":{"1":"27, 28"}},{"t":"law","label":"Pub. L. No. 104-153","url":"https://www.govinfo.gov/link/plaw/104/public/153","by":{"1":"54"}},{"t":"law","label":"Pub. L. No. 94-553","url":"https://www.govinfo.gov/link/statute/90/2541","by":{"1":"48, 55"}},{"t":"usc","label":"17 U.S.C. § 505","url":"https://www.law.cornell.edu/uscode/text/17/505","by":{"1":"48"}},{"t":"usc","label":"15 U.S.C. § 1065","url":"https://www.law.cornell.edu/uscode/text/15/1065","by":{"1":"44"}},{"t":"usc","label":"15 U.S.C. § 1114","url":"https://www.law.cornell.edu/uscode/text/15/1114","subs":["(1)","(1)(a)","(1)(b)","(2)(A)","(2)(B)","(2)"],"stext":{"head":"§1114. Remedies; infringement; innocent infringement by printers and publishers","paras":[[0,"(1) Any person who shall, without the consent of the registrant—"],[1,"(a) use in commerce any reproduction, counterfeit, copy, or colorable imitation of a registered mark in connection with the sale, offering for sale, distribution, or advertising of any goods or services on or in connection with which such use is likely to cause confusion, or to cause mistake, or to deceive; or"],[1,"(b) reproduce, counterfeit, copy, or colorably imitate a registered mark and apply such reproduction, counterfeit, copy, or colorable imitation to labels, signs, prints, packages, wrappers, receptacles or advertisements intended to be used in commerce upon or in connection with the sale, offering for sale, distribution, or advertising of goods or services on or in connection with which such use is likely to cause confusion, or to cause mistake, or to deceive,"],[0,"shall be liable in a civil action by the registrant for the remedies hereinafter provided. Under subsection (b) hereof, the registrant shall not be entitled to recover profits or damages unless the acts have been committed with knowledge that such imitation is intended to be used to cause confusion, or to cause mistake, or to deceive."],[0,"As used in this paragraph, the term \"any person\" includes the United States, all agencies and instrumentalities thereof, and all individuals, firms, corporations, or other persons acting for the United States and with the authorization and consent of the United States, and any State, any instrumentality of a State, and any officer or employee of a State or instrumentality of a State acting in his or her official capacity. The United States, all agencies and instrumentalities thereof, and all individuals, firms, corporations, other persons acting for the United States and with the authorization and consent of the United States, and any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"(2) Notwithstanding any other provision of this chapter, the remedies given to the owner of a right infringed under this chapter or to a person bringing an action under section 1125(a) or (d) of this title shall be limited as follows:"],[1,"(A) Where an infringer or violator is engaged solely in the business of printing the mark or violating matter for others and establishes that he or she was an innocent infringer or innocent violator, the owner of the right infringed or person bringing the action under section 1125(a) of this title shall be entitled as against such infringer or violator only to an injunction against future printing."],[1,"(B) Where the infringement or violation complained of is contained in or is part of paid advertising matter in a newspaper, magazine, or other similar periodical or in an electronic communication as defined in section 2510(12) of title 18, the remedies of the owner of the right infringed or person bringing the action under section 1125(a) of this title as against the publisher or distributor of such newspaper, magazine, or other similar periodical or electronic communication shall be limited to an injunction against the presentation of such advertising matter in future issues of such newspapers, magazines, or other similar periodicals or in future transmissions of such electronic communications. The limitations of this subparagraph shall apply only to innocent infringers and innocent violators."],[1,"(C) Injunctive relief shall not be available to the owner of the right infringed or person bringing the action under section 1125(a) of this title with respect to an issue of a newspaper, magazine, or other similar periodical or an electronic communication containing infringing matter or violating matter where restraining the dissemination of such infringing matter or violating matter in any particular issue of such periodical or in an electronic communication would delay the delivery of such issue or transmission of such electronic communication after the regular time for such delivery or transmission, and such delay would be due to the method by which publication and distribution of such periodical or transmission of such electronic communication is customarily conducted in accordance with sound business practice, and not due to any method or device adopted to evade this section or to prevent or delay the issuance of an injunction or restraining order with respect to such infringing matter or violating matter."],[1,"(D)(i)(I) A domain name registrar, a domain name registry, or other domain name registration authority that takes any action described under clause (ii) affecting a domain name shall not be liable for monetary relief or, except as provided in subclause (II), for injunctive relief, to any person for such action, regardless of whether the domain name is finally determined to infringe or dilute the mark."],[1,"(II) A domain name registrar, domain name registry, or other domain name registration authority described in subclause (I) may be subject to injunctive relief only if such registrar, registry, or other registration authority has—"],[2,"(aa) not expeditiously deposited with a court, in which an action has been filed regarding the disposition of the domain name, documents sufficient for the court to establish the court's control and authority regarding the disposition of the registration and use of the domain name;"],[2,"(bb) transferred, suspended, or otherwise modified the domain name during the pendency of the action, except upon order of the court; or"],[2,"(cc) willfully failed to comply with any such court order."],[1,"(ii) An action referred to under clause (i)(I) is any action of refusing to register, removing from registration, transferring, temporarily disabling, or permanently canceling a domain name—"],[2,"(I) in compliance with a court order under section 1125(d) of this title; or"],[2,"(II) in the implementation of a reasonable policy by such registrar, registry, or authority prohibiting the registration of a domain name that is identical to, confusingly similar to, or dilutive of another's mark."],[1,"(iii) A domain name registrar, a domain name registry, or other domain name registration authority shall not be liable for damages under this section for the registration or maintenance of a domain name for another absent a showing of bad faith intent to profit from such registration or maintenance of the domain name."],[1,"(iv) If a registrar, registry, or other registration authority takes an action described under clause (ii) based on a knowing and material misrepresentation by any other person that a domain name is identical to, confusingly similar to, or dilutive of a mark, the person making the knowing and material misrepresentation shall be liable for any damages, including costs and attorney's fees, incurred by the domain name registrant as a result of such action. The court may also grant injunctive relief to the domain name registrant, including the reactivation of the domain name or the transfer of the domain name to the domain name registrant."],[1,"(v) A domain name registrant whose domain name has been suspended, disabled, or transferred under a policy described under clause (ii)(II) may, upon notice to the mark owner, file a civil action to establish that the registration or use of the domain name by such registrant is not unlawful under this chapter. The court may grant injunctive relief to the domain name registrant, including the reactivation of the domain name or transfer of the domain name to the domain name registrant."],[1,"(E) As used in this paragraph—"],[2,"(i) the term \"violator\" means a person who violates section 1125(a) of this title; and"],[2,"(ii) the term \"violating matter\" means matter that is the subject of a violation under section 1125(a) of this title."],[0,"(3)(A) Any person who engages in the conduct described in paragraph (11) of section 110 of title 17 and who complies with the requirements set forth in that paragraph is not liable on account of such conduct for a violation of any right under this chapter. This subparagraph does not preclude liability, nor shall it be construed to restrict the defenses or limitations on rights granted under this chapter, of a person for conduct not described in paragraph (11) of section 110 of title 17, even if that person also engages in conduct described in paragraph (11) of section 110 of such title."],[0,"(B) A manufacturer, licensee, or licensor of technology that enables the making of limited portions of audio or video content of a motion picture imperceptible as described in subparagraph (A) is not liable on account of such manufacture or license for a violation of any right under this chapter, if such manufacturer, licensee, or licensor ensures that the technology provides a clear and conspicuous notice at the beginning of each performance that the performance of the motion picture is altered from the performance intended by the director or copyright holder of the motion picture. The limitations on liability in subparagraph (A) and this subparagraph shall not apply to a manufacturer, licensee, or licensor of technology that fails to comply with this paragraph."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1114?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1114. Remedies; infringement; innocent infringement by printers and publishers","tname":"Commerce and Trade","by":{"1":"16, 22, 25, 27, 5, 16, 25, 27, 25, 27, 25, 27, 25, 27","2":"passim, 6, 6"}},{"t":"usc","label":"15 U.S.C. § 1115","url":"https://www.law.cornell.edu/uscode/text/15/1115","subs":["(b)"],"by":{"1":"44"}},{"t":"usc","label":"15 U.S.C. § 1117","url":"https://www.law.cornell.edu/uscode/text/15/1117","subs":["(a)","(a)(1996)","(b)","(b)(1)","(b)(2)","(c)","(c)(1)","(c)(2)"],"stext":{"head":"§1117. Recovery for violation of rights","paras":[[0,"(a) Profits; damages and costs; attorney fees"],[0,"When a violation of any right of the registrant of a mark registered in the Patent and Trademark Office, a violation under section 1125(a) or (d) of this title, or a willful violation under section 1125(c) of this title, shall have been established in any civil action arising under this chapter, the plaintiff shall be entitled, subject to the provisions of sections 1111 and 1114 of this title, and subject to the principles of equity, to recover (1) defendant's profits, (2) any damages sustained by the plaintiff, and (3) the costs of the action. The court shall assess such profits and damages or cause the same to be assessed under its direction. In assessing profits the plaintiff shall be required to prove defendant's sales only; defendant must prove all elements of cost or deduction claimed. In assessing damages the court may enter judgment, according to the circumstances of the case, for any sum above the amount found as actual damages, not exceeding three times such amount. If the court shall find that the amount of the recovery based on profits is either inadequate or excessive the court may in its discretion enter judgment for such sum as the court shall find to be just, according to the circumstances of the case. Such sum in either of the above circumstances shall constitute compensation and not a penalty. The court in exceptional cases may award reasonable attorney fees to the prevailing party."],[0,"(b) Treble damages for use of counterfeit mark"],[0,"In assessing damages under subsection (a) for any violation of section 1114(1)(a) of this title or section 220506 of title 36, in a case involving use of a counterfeit mark or designation (as defined in section 1116(d) of this title), the court shall, unless the court finds extenuating circumstances, enter judgment for three times such profits or damages, whichever amount is greater, together with a reasonable attorney's fee, if the violation consists of—"],[1,"(1) intentionally using a mark or designation, knowing such mark or designation is a counterfeit mark (as defined in section 1116(d) of this title), in connection with the sale, offering for sale, or distribution of goods or services; or"],[1,"(2) providing goods or services necessary to the commission of a violation specified in paragraph (1), with the intent that the recipient of the goods or services would put the goods or services to use in committing the violation."],[0,"In such a case, the court may award prejudgment interest on such amount at an annual interest rate established under section 6621(a)(2) of title 26, beginning on the date of the service of the claimant's pleadings setting forth the claim for such entry of judgment and ending on the date such entry is made, or for such shorter time as the court considers appropriate."],[0,"(c) Statutory damages for use of counterfeit marks"],[0,"In a case involving the use of a counterfeit mark (as defined in section 1116(d) of this title) in connection with the sale, offering for sale, or distribution of goods or services, the plaintiff may elect, at any time before final judgment is rendered by the trial court, to recover, instead of actual damages and profits under subsection (a), an award of statutory damages for any such use in connection with the sale, offering for sale, or distribution of goods or services in the amount of—"],[1,"(1) not less than $1,000 or more than $200,000 per counterfeit mark per type of goods or services sold, offered for sale, or distributed, as the court considers just; or"],[1,"(2) if the court finds that the use of the counterfeit mark was willful, not more than $2,000,000 per counterfeit mark per type of goods or services sold, offered for sale, or distributed, as the court considers just."],[0,"(d) Statutory damages for violation of section 1125(d)(1)"],[0,"In a case involving a violation of section 1125(d)(1) of this title, the plaintiff may elect, at any time before final judgment is rendered by the trial court, to recover, instead of actual damages and profits, an award of statutory damages in the amount of not less than $1,000 and not more than $100,000 per domain name, as the court considers just."],[0,"(e) Rebuttable presumption of willful violation"],[0,"In the case of a violation referred to in this section, it shall be a rebuttable presumption that the violation is willful for purposes of determining relief if the violator, or a person acting in concert with the violator, knowingly provided or knowingly caused to be provided materially false contact information to a domain name registrar, domain name registry, or other domain name registration authority in registering, maintaining, or renewing a domain name used in connection with the violation. Nothing in this subsection limits what may be considered a willful violation under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1117?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1117. Recovery for violation of rights","tname":"Commerce and Trade","by":{"1":"passim, 9, 24, 27, 28, 28, 28, 26, 27, 6, 27","2":"passim, 6, 5, 6, 20"}},{"t":"usc","label":"15 U.S.C. § 1125","url":"https://www.law.cornell.edu/uscode/text/15/1125","subs":["(a)","(c)","(c)(5)(B)","(d)","(c)(5)(B)(i)","(c)(5)(B)(ii)"],"stext":{"head":"§1125. False designations of origin, false descriptions, and dilution forbidden","paras":[[0,"(a) Civil action"],[0,"(1) Any person who, on or in connection with any goods or services, or any container for goods, uses in commerce any word, term, name, symbol, or device, or any combination thereof, or any false designation of origin, false or misleading description of fact, or false or misleading representation of fact, which—"],[1,"(A) is likely to cause confusion, or to cause mistake, or to deceive as to the affiliation, connection, or association of such person with another person, or as to the origin, sponsorship, or approval of his or her goods, services, or commercial activities by another person, or"],[1,"(B) in commercial advertising or promotion, misrepresents the nature, characteristics, qualities, or geographic origin of his or her or another person's goods, services, or commercial activities,"],[0,"shall be liable in a civil action by any person who believes that he or she is or is likely to be damaged by such act."],[0,"(2) As used in this subsection, the term \"any person\" includes any State, instrumentality of a State or employee of a State or instrumentality of a State acting in his or her official capacity. Any State, and any such instrumentality, officer, or employee, shall be subject to the provisions of this chapter in the same manner and to the same extent as any nongovernmental entity."],[0,"(3) In a civil action for trade dress infringement under this chapter for trade dress not registered on the principal register, the person who asserts trade dress protection has the burden of proving that the matter sought to be protected is not functional."],[0,"(b) Importation"],[0,"Any goods marked or labeled in contravention of the provisions of this section shall not be imported into the United States or admitted to entry at any customhouse of the United States. The owner, importer, or consignee of goods refused entry at any customhouse under this section may have any recourse by protest or appeal that is given under the customs revenue laws or may have the remedy given by this chapter in cases involving goods refused entry or seized."],[0,"(c) Dilution by blurring; dilution by tarnishment"],[0,"(1) Injunctive relief"],[1,"Subject to the principles of equity, the owner of a famous mark that is distinctive, inherently or through acquired distinctiveness, shall be entitled to an injunction against another person who, at any time after the owner's mark has become famous, commences use of a mark or trade name in commerce that is likely to cause dilution by blurring or dilution by tarnishment of the famous mark, regardless of the presence or absence of actual or likely confusion, of competition, or of actual economic injury."],[0,"(2) Definitions"],[1,"(A) For purposes of paragraph (1), a mark is famous if it is widely recognized by the general consuming public of the United States as a designation of source of the goods or services of the mark's owner. In determining whether a mark possesses the requisite degree of recognition, the court may consider all relevant factors, including the following:"],[2,"(i) The duration, extent, and geographic reach of advertising and publicity of the mark, whether advertised or publicized by the owner or third parties."],[2,"(ii) The amount, volume, and geographic extent of sales of goods or services offered under the mark."],[2,"(iii) The extent of actual recognition of the mark."],[2,"(iv) Whether the mark was registered under the Act of March 3, 1881, or the Act of February 20, 1905, or on the principal register."],[1,"(B) For purposes of paragraph (1), \"dilution by blurring\" is association arising from the similarity between a mark or trade name and a famous mark that impairs the distinctiveness of the famous mark. In determining whether a mark or trade name is likely to cause dilution by blurring, the court may consider all relevant factors, including the following:"],[2,"(i) The degree of similarity between the mark or trade name and the famous mark."],[2,"(ii) The degree of inherent or acquired distinctiveness of the famous mark."],[2,"(iii) The extent to which the owner of the famous mark is engaging in substantially exclusive use of the mark."],[2,"(iv) The degree of recognition of the famous mark."],[2,"(v) Whether the user of the mark or trade name intended to create an association with the famous mark."],[2,"(vi) Any actual association between the mark or trade name and the famous mark."],[1,"(C) For purposes of paragraph (1), \"dilution by tarnishment\" is association arising from the similarity between a mark or trade name and a famous mark that harms the reputation of the famous mark."],[0,"(3) Exclusions"],[1,"The following shall not be actionable as dilution by blurring or dilution by tarnishment under this subsection:"],[2,"(A) Any fair use, including a nominative or descriptive fair use, or facilitation of such fair use, of a famous mark by another person other than as a designation of source for the person's own goods or services, including use in connection with—"],[3,"(i) advertising or promotion that permits consumers to compare goods or services; or"],[3,"(ii) identifying and parodying, criticizing, or commenting upon the famous mark owner or the goods or services of the famous mark owner."],[2,"(B) All forms of news reporting and news commentary."],[2,"(C) Any noncommercial use of a mark."],[0,"(4) Burden of proof"],[1,"In a civil action for trade dress dilution under this chapter for trade dress not registered on the principal register, the person who asserts trade dress protection has the burden of proving that—"],[2,"(A) the claimed trade dress, taken as a whole, is not functional and is famous; and"],[2,"(B) if the claimed trade dress includes any mark or marks registered on the principal register, the unregistered matter, taken as a whole, is famous separate and apart from any fame of such registered marks."],[0,"(5) Additional remedies"],[1,"In an action brought under this subsection, the owner of the famous mark shall be entitled to injunctive relief as set forth in section 1116 of this title. The owner of the famous mark shall also be entitled to the remedies set forth in sections 1117(a) and 1118 of this title, subject to the discretion of the court and the principles of equity if—"],[2,"(A) the mark or trade name that is likely to cause dilution by blurring or dilution by tarnishment was first used in commerce by the person against whom the injunction is sought after October 6, 2006; and"],[2,"(B) in a claim arising under this subsection—"],[3,"(i) by reason of dilution by blurring, the person against whom the injunction is sought willfully intended to trade on the recognition of the famous mark; or"],[3,"(ii) by reason of dilution by tarnishment, the person against whom the injunction is sought willfully intended to harm the reputation of the famous mark."],[0,"(6) Ownership of valid registration a complete bar to action"],[1,"The ownership by a person of a valid registration under the Act of March 3, 1881, or the Act of February 20, 1905, or on the principal register under this chapter shall be a complete bar to an action against that person, with respect to that mark, that—"],[2,"(A) is brought by another person under the common law or a statute of a State; and"],[2,"(B)(i) seeks to prevent dilution by blurring or dilution by tarnishment; or"],[2,"(ii) asserts any claim of actual or likely damage or harm to the distinctiveness or reputation of a mark, label, or form of advertisement."],[0,"(7) Savings clause"],[1,"Nothing in this subsection shall be construed to impair, modify, or supersede the applicability of the patent laws of the United States."],[0,"(d) Cyberpiracy prevention"],[0,"(1)(A) A person shall be liable in a civil action by the owner of a mark, including a personal name which is protected as a mark under this section, if, without regard to the goods or services of the parties, that person—"],[1,"(i) has a bad faith intent to profit from that mark, including a personal name which is protected as a mark under this section; and"],[1,"(ii) registers, traffics in, or uses a domain name that—"],[2,"(I) in the case of a mark that is distinctive at the time of registration of the domain name, is identical or confusingly similar to that mark;"],[2,"(II) in the case of a famous mark that is famous at the time of registration of the domain name, is identical or confusingly similar to or dilutive of that mark; or"],[2,"(III) is a trademark, word, or name protected by reason of section 706 of title 18 or section 220506 of title 36."],[0,"(B)(i) In determining whether a person has a bad faith intent described under subparagraph (A), a court may consider factors such as, but not limited to—"],[1,"(I) the trademark or other intellectual property rights of the person, if any, in the domain name;"],[1,"(II) the extent to which the domain name consists of the legal name of the person or a name that is otherwise commonly used to identify that person;"],[1,"(III) the person's prior use, if any, of the domain name in connection with the bona fide offering of any goods or services;"],[1,"(IV) the person's bona fide noncommercial or fair use of the mark in a site accessible under the domain name;"],[1,"(V) the person's intent to divert consumers from the mark owner's online location to a site accessible under the domain name that could harm the goodwill represented by the mark, either for commercial gain or with the intent to tarnish or disparage the mark, by creating a likelihood of confusion as to the source, sponsorship, affiliation, or endorsement of the site;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1125?type=usc&year=mostrecent&link-type=html"},"head":"§1125. False designations of origin, false descriptions, and dilution forbidden","tname":"Commerce and Trade","by":{"1":"5, 16, 24, 27, passim, 23, 16, 28","2":"passim, 1, 3, 4, 5, 3, 3, 3, 7, 10"}},{"t":"usc","label":"35 U.S.C. § 284","url":"https://www.law.cornell.edu/uscode/text/35/284","by":{"1":"47"}},{"t":"usc","label":"35 U.S.C. § 285","url":"https://www.law.cornell.edu/uscode/text/35/285","by":{"1":"49"}},{"t":"usc","label":"35 U.S.C. § 289","url":"https://www.law.cornell.edu/uscode/text/35/289","by":{"1":"55"}},{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"sum":"The Court held that the jury instructions failed to convey that the federal document law required a \"consciousness of wrongdoing\" for conviction. There was nothing inherently corrupt in ordering employees to destroy documents, even if the aim was to keep the documents from the government.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Black Hills Jewelry Mfg. Co. v. Gold Rush, Inc.","cite":"633 F.2d 746","y":1980,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/633/746/","op":2,"by":{"2":"11"}},{"t":"case","label":"Bridge v. Phx. Bond & Indem. Co.","cite":"553 U.S. 639","y":2008,"id":"2007/07-210","sc":1,"sum":"The Court held in favor of Phoenix, stating that a plaintiff bringing a RICO claim based on mail fraud does not need to show that it actually relied on the defendant's misrepresentations. Plaintiffs do not lack standing merely because the false statements were made to a third party.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Mishawaka Rubber & Woolen Mfg. Co. v. S.S. Kresge Co.","cite":"67 F. Supp. 1000","y":1946,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp./67/1000/","by":{"2":"14"}},{"t":"usc","label":"15 U.S.C. § 1116","url":"https://www.law.cornell.edu/uscode/text/15/1116","subs":["(a)"],"by":{"2":"3, 3, 9"}},{"t":"usc","label":"15 U.S.C. § 1118","url":"https://www.law.cornell.edu/uscode/text/15/1118","stext":{"head":"§1118. Destruction of infringing articles","paras":[[0,"In any action arising under this chapter, in which a violation of any right of the registrant of a mark registered in the Patent and Trademark Office, a violation under section 1125(a) of this title, or a willful violation under section 1125(c) of this title, shall have been established, the court may order that all labels, signs, prints, packages, wrappers, receptacles, and advertisements in the possession of the defendant, bearing the registered mark or, in the case of a violation of section 1125(a) of this title or a willful violation under section 1125(c) of this title, the word, term, name, symbol, device, combination thereof, designation, description, or representation that is the subject of the violation, or any reproduction, counterfeit, copy, or colorable imitation thereof, and all plates, molds, matrices, and other means of making the same, shall be delivered up and destroyed. The party seeking an order under this section for destruction of articles seized under section 1116(d) of this title shall give ten days' notice to the United States attorney for the judicial district in which such order is sought (unless good cause is shown for lesser notice) and such United States attorney may, if such destruction may affect evidence of an offense against the United States, seek a hearing on such destruction or participate in any hearing otherwise to be held with respect to such destruction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1118?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1118. Destruction of infringing articles","tname":"Commerce and Trade","by":{"2":"3"}}]};